def validate_batch(records):
    if type(records) is not list:
        raise ValueError("expected a list")
    accepted, rejected, seen = [], [], set()
    total_cents = 0
    required = {"trade_id", "price_cents", "quantity_shares"}
    for index, record in enumerate(records):
        reason = None
        if type(record) is not dict or set(record) != required:
            reason = "fields"
        elif type(record["trade_id"]) is not str or not record["trade_id"]:
            reason = "id"
        elif any(type(record[key]) is not int or record[key] < 0
                 for key in ["price_cents", "quantity_shares"]):
            reason = "numeric"
        elif record["trade_id"] in seen:
            reason = "duplicate"
        if reason is not None:
            rejected.append({"index": index, "reason": reason})
            continue
        item = record.copy()
        accepted.append(item)
        seen.add(item["trade_id"])
        total_cents += item["price_cents"] * item["quantity_shares"]
    return {"accepted": accepted, "rejected": rejected, "total_cents": total_cents}

