from copy import deepcopy
sample = [{"trade_id": "A", "price_cents": 2, "quantity_shares": 3},
          {"trade_id": "A", "price_cents": 2, "quantity_shares": 1}]
before = deepcopy(sample)
result = validate_batch(sample)
if sample != before:
    raise AssertionError("input changed")
if len(result["accepted"]) + len(result["rejected"]) != len(sample):
    raise AssertionError("report count mismatch")
if result["total_cents"] != 6:
    raise AssertionError("notional mismatch")
print("contract checks passed")

MOD = 1000000007

def price_units(text):
    (whole, dot, fractional) = text.partition('.')
    return int(whole) * 10000 + int(fractional.ljust(4, '0') if dot else '0')

def verdict(line, seen_ids, last_ts):
    import re
    fields = line.split(',')
    if len(fields) != 6:
        return 'BAD_FIELDS'
    (identifier, symbol, side, quantity, price, timestamp) = fields
    if re.fullmatch('[A-Za-z0-9]+', identifier) is None:
        return 'BAD_ID'
    if re.fullmatch('[A-Z]{1,6}', symbol) is None:
        return 'BAD_SYMBOL'
    if side not in ('B', 'S'):
        return 'BAD_SIDE'
    if re.fullmatch('[1-9][0-9]*', quantity) is None or int(quantity) > 10 ** 9:
        return 'BAD_QTY'
    if re.fullmatch('[0-9]+(?:\\.[0-9]{1,4})?', price) is None or price_units(price) <= 0:
        return 'BAD_PRICE'
    if re.fullmatch('0|[1-9][0-9]*', timestamp) is None or int(timestamp) > 10 ** 12:
        return 'BAD_TS'
    if identifier in seen_ids:
        return 'DUP_ID'
    if int(timestamp) < last_ts:
        return 'OUT_OF_ORDER'
    return None

def process_records(lines):
    (seen, last, valid, total) = (set(), 0, 0, 0)
    out = []
    for line in lines:
        error = verdict(line, seen, last)
        out.append(error or 'OK')
        if error is None:
            (identifier, _, _, quantity, price, timestamp) = line.split(',')
            seen.add(identifier)
            last = int(timestamp)
            valid += 1
            total += int(quantity) * price_units(price)
    return out + [f'VALID {valid}', f'NOTIONAL {total // 10000}.{total % 10000:04d}']

print(process_records(['A,X,B,1,1,5', 'B,X,B,1,1,4', 'B,X,S,2,0.0001,5', 'A,X,Q,1,1,1']))
print(verdict('T_1,X,B,1,1,0', set(), 0))
